684	  const groups = new Map();
685	  missed.forEach((flag) => {
686	    const key = flag.toLowerCase().replace(/\s+/g, " ");
687	    const hit = groups.get(key);
688	    if (hit) hit.n++;
689	    else groups.set(key, { text: flag, n: 1 });
690	  });
691	  const items = [...groups.values()].sort((a, b) => b.n - a.n);
692	
693	  $("recap").innerHTML = `<h3>Red flags you missed this run</h3>` + (items.length
694	    ? `<ul>${items.map((g) => `<li>${esc(g.text)}${g.n > 1 ? ` <span class="count">×${g.n}</span>` : ""}</li>`).join("")}</ul>`
695	    : `<p class="clean">You caught every red flag!</p>`);
