454	.sms .link { padding: 10px 0 0; }
455	.sms .link-chip { font-family: monospace; font-weight: 400; color: var(--teal); }
456	.sms .link-chip:focus-visible { outline-color: var(--teal); }
457	.sms .link-hint { background: #1d2a3d; color: var(--muted); }
458	
459	/* The popup that shows a link's real destination */
460	.link-peek {
