const puppeteer = require("puppeteer-core");
const OUT = __dirname;
const sizes = [
  { name: "desktop", width: 1920, height: 1080 },
  { name: "phone", width: 375, height: 812, isMobile: true, hasTouch: true, deviceScaleFactor: 2 },
];

(async () => {
  const browser = await puppeteer.launch({
    executablePath: "C:/Program Files/Google/Chrome/Application/chrome.exe",
    headless: "new",
  });
  for (const vp of sizes) {
    const ctx = await browser.createBrowserContext();
    const page = await ctx.newPage();
    const errors = [];
    page.on("pageerror", (e) => errors.push(e.message));
    await page.setViewport(vp);
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });

    const startRun = async () => {
      await page.type("#username", "Tester");
      await page.click('.mode[data-mode="easy"]');
      await page.click("#btn-start");
      await page.waitForSelector("#message .email, #message .sms");
      await new Promise((r) => setTimeout(r, 300));
    };
    const state = () => page.evaluate(() => {
      const t = document.querySelector(".tutorial");
      const r = t.getBoundingClientRect();
      const tg = document.querySelector(".tut-target");
      return {
        shown: !t.hidden, text: t.querySelector(".tut-text")?.textContent, side: t.dataset.side,
        inView: r.left >= 0 && r.top >= 0 && r.right <= document.documentElement.clientWidth && r.bottom <= innerHeight,
        overlapsTarget: tg ? !(r.bottom <= tg.getBoundingClientRect().top || r.top >= tg.getBoundingClientRect().bottom) : null,
        target: tg ? tg.className : null, hScroll: document.documentElement.scrollWidth > document.documentElement.clientWidth,
        box: [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)],
      };
    });

    await startRun();
    for (let i = 1; i <= 3; i++) {
      console.log(vp.name, "step", i, JSON.stringify(await state()));
      await page.screenshot({ path: `${OUT}/${vp.name}-step${i}.png` });
      await page.click(".tut-ok");
      await new Promise((r) => setTimeout(r, 200));
    }
    console.log(vp.name, "after 3 Got it:", JSON.stringify(await state()),
      "stored:", await page.evaluate(() => localStorage.getItem("ps-tutorial-seen")));

    // Second run: no tutorial
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
    await startRun();
    console.log(vp.name, "second run shown:", (await state()).shown);

    // Replay with ? then skip
    await page.click("#btn-tutorial");
    await new Promise((r) => setTimeout(r, 200));
    console.log(vp.name, "replay:", JSON.stringify(await state()));
    await page.screenshot({ path: `${OUT}/${vp.name}-topbar.png`, clip: { x: 0, y: 0, width: vp.width, height: 120 } });
    await page.click(".tut-skip");
    console.log(vp.name, "after skip shown:", (await state()).shown);

    // Answering closes it
    await page.click("#btn-tutorial");
    await page.click("#btn-phish");
    await new Promise((r) => setTimeout(r, 300));
    console.log(vp.name, "after answer shown:", (await state()).shown, "errors:", errors);
    await ctx.close();
  }
  await browser.close();
})();

