// Fresh state each case: new browser context (empty localStorage), one forced scenario.
const puppeteer = require("puppeteer-core");
const OUT = __dirname;
const CASES = [
  { id: 2, label: "email-link" },
  { id: 1, label: "email-nolink" },
  { id: 8, label: "sms-nolink" },
  { id: 3, label: "sms-link" },
];
const VIEWPORTS = [
  { name: "desktop", width: 1920, height: 1080 },
  { name: "phone", width: 375, height: 812, isMobile: true, hasTouch: true, deviceScaleFactor: 2 },
];
const shots = process.argv.includes("--shots");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({ executablePath: "C:/Program Files/Google/Chrome/Application/chrome.exe", headless: "new" });
  let fails = 0;
  for (const vp of VIEWPORTS) for (const c of CASES) {
    const ctx = await browser.createBrowserContext();
    const page = await ctx.newPage();
    const errors = [];
    page.on("pageerror", (e) => errors.push(e.message));
    await page.setViewport(vp);
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
    await page.evaluate((id) => {
      localStorage.removeItem("ps-tutorial-seen");
      const keep = MOCK_SCENARIOS.filter((s) => s.scenario_id === id).map((s) => ({ ...s, difficulty: "easy" }));
      MOCK_SCENARIOS.splice(0, MOCK_SCENARIOS.length, ...keep);
    }, c.id);
    await page.type("#username", "NewPlayer");
    await page.click('.mode[data-mode="easy"]');
    await page.click("#btn-start");
    await page.waitForSelector("#message .email, #message .sms");
    await sleep(400);

    const st = () => page.evaluate(() => {
      const t = document.querySelector(".tutorial");
      const r = t.getBoundingClientRect();
      const tg = document.querySelector(".tut-target");
      return {
        shown: !t.hidden,
        count: t.querySelector(".tut-count")?.textContent,
        target: tg ? tg.tagName.toLowerCase() + "." + [...tg.classList].filter((k) => k !== "tut-target").join(".") : null,
        inView: r.left >= 0 && r.top >= 0 && r.right <= document.documentElement.clientWidth && r.bottom <= innerHeight,
        seen: localStorage.getItem("ps-tutorial-seen"),
      };
    });
    const steps = [];
    for (let i = 1; i <= 3; i++) {
      const s = await st();
      steps.push(s);
      if (shots && s.shown) await page.screenshot({ path: `${OUT}/fix-${vp.name}-${c.label}-${i}.png` });
      if (!s.shown) break;
      await page.click(".tut-ok");
      await sleep(150);
    }
    const end = await st();
    const ok = steps.length === 3 && steps.every((s) => s.shown && s.inView && s.seen === null) && !end.shown && end.seen === "1" && !errors.length;
    if (!ok) fails++;
    console.log(`${ok ? "PASS" : "FAIL"} ${vp.name} ${c.label}: ` +
      steps.map((s) => (s.shown ? `${s.count} -> ${s.target}${s.inView ? "" : " (OFF SCREEN)"} seen=${s.seen}` : `not shown (seen=${s.seen})`)).join(" | ") +
      ` | end seen=${end.seen}${errors.length ? " ERRORS " + errors.join("; ") : ""}`);
    await ctx.close();
  }

  // Skip saves the flag; answering mid-tutorial does not; "?" still replays.
  const ctx = await browser.createBrowserContext();
  const page = await ctx.newPage();
  await page.setViewport(VIEWPORTS[0]);
  await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
  const flag = () => page.evaluate(() => localStorage.getItem("ps-tutorial-seen"));
  const shown = () => page.evaluate(() => !document.querySelector(".tutorial").hidden);
  await page.type("#username", "NewPlayer");
  await page.click('.mode[data-mode="easy"]');
  await page.click("#btn-start");
  await page.waitForSelector("#message .email, #message .sms");
  await sleep(300);
  const a = [await shown(), await flag()];
  await page.click("#btn-phish");
  await sleep(1800);
  const b = [await shown(), await flag()];
  await page.click("#btn-tutorial");
  await sleep(150);
  const c = await shown();
  await page.click(".tut-skip");
  const d = [await shown(), await flag()];
  const ok = a[0] && a[1] === null && !b[0] && b[1] === null && c && !d[0] && d[1] === "1";
  if (!ok) fails++;
  console.log(`${ok ? "PASS" : "FAIL"} flags: start shown=${a[0]} seen=${a[1]} | after answering shown=${b[0]} seen=${b[1]} | "?" replays=${c} | after skip shown=${d[0]} seen=${d[1]}`);
  await ctx.close();
  await browser.close();
  console.log(fails ? `${fails} FAILED` : "ALL PASSED");
})();

