388	window.addEventListener("resize", placePeek);
389	
390	// ---------- First-round tutorial ----------
391	// The first time a player starts a run, three callouts point at the sender,
392	// the link, and the Phish / Legit buttons, one at a time. The "?" button in
393	// the top bar replays it. Callouts never block the game: answering closes them.
394	const TUTORIAL_KEY = "ps-tutorial-seen";
395	const canHover = () => window.matchMedia("(hover: hover)").matches;
396	const TUTORIAL_STEPS = [
397	  {
398	    target: () => document.querySelector("#message .from, #message .sms .label"),
399	    text: () => "Check who it's really from. Compare it to your trusted contacts.",
400	  },
401	  {
402	    // Point at the link, or at the message itself when there's no link
403	    target: () => document.querySelector("#message .link-chip") || document.querySelector("#message .body, #message .bubble"),
404	    text: () => `${canHover() ? "Hover" : "Tap"} links to see where they really go.`,
405	  },
406	  {
407	    target: () => document.querySelector("#play-screen .answers"),
408	    text: () => "Decide: Phish or Legit?",
409	  },
410	];
411	
412	function tutorialSeen() {
413	  try { return localStorage.getItem(TUTORIAL_KEY) === "1"; } catch (e) { return false; }
414	}
415	function markTutorialSeen() {
416	  try { localStorage.setItem(TUTORIAL_KEY, "1"); } catch (e) {}
417	}
418	
419	const tut = document.createElement("div");
420	tut.className = "tutorial";
421	tut.setAttribute("role", "dialog");
422	tut.setAttribute("aria-labelledby", "tut-text");
423	tut.hidden = true;
424	document.body.appendChild(tut);
425	
426	let tutStep = -1;      // -1 when the tutorial isn't showing
427	let tutTarget = null;  // the element the current callout points at
428	let tutReturn = null;  // where keyboard focus goes back to afterwards
429	
430	const messageReady = () => !!document.querySelector("#message .email, #message .sms");
431	
432	function startTutorial() {
433	  if (!messageReady()) return;
434	  hidePeek();
435	  if (tutStep < 0) tutReturn = document.activeElement;
436	  tutStep = 0;
437	  $("btn-tutorial").classList.add("open");
438	  showTutorialStep();
439	}
440	
441	function clearTutorialTarget() {
442	  if (tutTarget) tutTarget.classList.remove("tut-target");
443	  tutTarget = null;
444	}
445	
446	function showTutorialStep() {
447	  clearTutorialTarget();
448	  // Skip any step whose target isn't on the page
449	  while (tutStep < TUTORIAL_STEPS.length && !TUTORIAL_STEPS[tutStep].target()) tutStep++;
450	  if (tutStep >= TUTORIAL_STEPS.length) return endTutorial();
451	
452	  const step = TUTORIAL_STEPS[tutStep];
453	  tutTarget = step.target();
454	  tutTarget.classList.add("tut-target");
455	  tut.innerHTML = `
